#!/usr/bin/env python3
from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
from pathlib import Path


def find_repo() -> Path:
    env = os.environ.get("JACOBIAN_RESEARCH")
    candidates = []
    if env:
        candidates.append(Path(env).expanduser())
    cwd = Path.cwd().resolve()
    candidates.extend([cwd, *cwd.parents])
    home = Path.home()
    candidates.extend([
        home / "jacobian-research",
        home / "GitHub" / "jacobian-research",
        home / "github" / "jacobian-research",
        home / "Documents" / "jacobian-research",
        home / "Documents" / "GitHub" / "jacobian-research",
        home / "Developer" / "jacobian-research",
        home / "Projects" / "jacobian-research",
    ])
    marker = Path("elkies-k3/scripts/classify_kumar_cm_frame_extensions.sage")
    seen = set()
    for candidate in candidates:
        try:
            candidate = candidate.resolve()
        except Exception:
            continue
        if candidate in seen:
            continue
        seen.add(candidate)
        if (candidate / marker).exists():
            return candidate
    raise SystemExit(
        "Could not locate jacobian-research. "
        "Set JACOBIAN_RESEARCH=/path/to/jacobian-research."
    )


SAGE_CODE = '\nfrom __future__ import print_function\n\nimport csv\nimport sys\nfrom itertools import product\nfrom pathlib import Path\n\nfrom sage.all import (\n    QQ, ZZ, QuadraticForm, block_diagonal_matrix, ceil, floor, gcd,\n    matrix, vector, xgcd\n)\nfrom sage.repl.preparse import preparse_file\n\n\nROOT = Path(sys.argv[1]).resolve()\nSCRIPTS = ROOT / "elkies-k3" / "scripts"\nDATA = ROOT / "elkies-k3" / "data" / "fibrations"\nCLASSIFY = SCRIPTS / "classify_kumar_cm_frame_extensions.sage"\n\n# Load only the deterministic classifier prefix through the certified Q80 CM24\n# frame.  Do not execute its later exploratory searches.\nsource = CLASSIFY.read_text()\ncut_marker = "assert q80_cm24_profiles[3] == q80_cm24_optimal[1]"\ncut = source.find(cut_marker)\nassert cut >= 0\ncut += len(cut_marker)\nprefix = source[:cut] + "\\n"\nassert "q80_cm24, q80_embedding24" in prefix\nassert "level79_weyl_orbits" in source[cut:]\n\nsaved_argv = list(sys.argv)\nsaved_file = globals().get("__file__", None)\nsys.argv = [str(CLASSIFY), "--search-max-q", "0", "--orbit-counts-only"]\nglobals()["__file__"] = str(CLASSIFY)\ntry:\n    exec(preparse_file(prefix), globals())\nfinally:\n    sys.argv = saved_argv\n    if saved_file is None:\n        globals().pop("__file__", None)\n    else:\n        globals()["__file__"] = saved_file\n\nU = matrix(ZZ, [[0,1],[1,0]])\n\n\ndef load_matrix(path):\n    return matrix(\n        ZZ,\n        [\n            [ZZ(value) for value in line.split()]\n            for line in path.read_text().splitlines()\n            if line.strip() and not line.startswith("#")\n        ],\n    )\n\n\ndef bezout_vector(pairings):\n    current = ZZ(0)\n    coeffs = [ZZ(0)] * len(pairings)\n    for i, pairing in enumerate(pairings):\n        pairing = ZZ(pairing)\n        if not pairing:\n            continue\n        g, left, right = xgcd(current, pairing)\n        coeffs = [left*c for c in coeffs]\n        coeffs[i] += right\n        current = g\n    assert abs(current) == 1\n    if current == -1:\n        coeffs = [-c for c in coeffs]\n    return vector(ZZ, coeffs)\n\n\ndef neighbor(parent, qnorm, a, b, coordinates):\n    ns = block_diagonal_matrix(U, -parent)\n    coordinates = vector(ZZ, coordinates)\n    fiber = vector(ZZ, [a,b] + list(coordinates))\n    assert a*b == qnorm\n    assert coordinates*parent*coordinates == 2*qnorm\n    assert fiber*ns*fiber == 0\n    assert gcd([abs(ZZ(x)) for x in ns*fiber]) == 1\n\n    mate = bezout_vector(list(ns*fiber))\n    mate -= ZZ(mate*ns*mate)//2 * fiber\n    assert fiber*ns*mate == 1\n    assert mate*ns*mate == 0\n\n    complement = matrix(\n        ZZ, [list(fiber*ns), list(mate*ns)]\n    ).right_kernel_matrix()\n    child = -(complement*ns*complement.transpose())\n    transport = matrix(\n        ZZ,\n        [list(fiber), list(mate)] + [list(row) for row in complement.rows()],\n    )\n    assert abs(transport.det()) == 1\n    return child, transport\n\n\ndef enhance_neighbor(transport, embedding, special_frame):\n    lifted = [\n        vector(\n            ZZ,\n            list(row[:2]) + list(vector(ZZ,row[2:])*embedding),\n        )\n        for row in transport.rows()\n    ]\n    special_ns = block_diagonal_matrix(U, -special_frame)\n    fiber,mate = lifted[:2]\n    assert fiber*special_ns*fiber == 0\n    assert mate*special_ns*mate == 0\n    assert fiber*special_ns*mate == 1\n\n    complement = matrix(\n        ZZ, [list(fiber*special_ns), list(mate*special_ns)]\n    ).right_kernel_matrix()\n    basis = matrix(\n        ZZ,\n        [list(fiber), list(mate)] + [list(row) for row in complement.rows()],\n    )\n    assert abs(basis.det()) == 1\n    child = -(complement*special_ns*complement.transpose())\n    inverse_basis = basis.inverse()\n\n    embedding_rows = []\n    for row in lifted[2:]:\n        coordinates = row*inverse_basis\n        assert coordinates[0] == coordinates[1] == 0\n        embedding_rows.append(list(coordinates[2:]))\n    child_embedding = matrix(ZZ, embedding_rows)\n    return child, child_embedding\n\n\ndef roots_of_norm_two(gram):\n    half = QuadraticForm(ZZ, gram).short_vector_list_up_to_length(\n        2, up_to_sign_flag=True\n    )[1]\n    half = [vector(ZZ,row) for row in half]\n    return half + [-row for row in half]\n\n\ndef lex_positive(row):\n    return next(value > 0 for value in row if value)\n\n\ndef deterministic_simple_roots_local(gram):\n    roots = roots_of_norm_two(gram)\n    positive = [r for r in roots if lex_positive(r)]\n    positive_set = {tuple(r) for r in positive}\n    simple = []\n    for r in positive:\n        if not any(\n            tuple(r-s) in positive_set\n            for s in positive if s != r\n        ):\n            simple.append(r)\n    simple = matrix(ZZ, [list(r) for r in simple])\n    assert simple.nrows() == simple.rank()\n    return simple, positive\n\n\ndef connected_components_local(cartan):\n    unseen = set(range(cartan.nrows()))\n    answer = []\n    while unseen:\n        first = min(unseen)\n        unseen.remove(first)\n        todo = [first]\n        component = []\n        while todo:\n            i = todo.pop()\n            component.append(i)\n            for j in list(unseen):\n                if cartan[i,j]:\n                    unseen.remove(j)\n                    todo.append(j)\n        answer.append(tuple(sorted(component)))\n    return tuple(sorted(answer, key=lambda c:(len(c),c)))\n\n\ndef highest_roots_local(gram, simple, positive):\n    components = connected_components_local(\n        simple*gram*simple.transpose()\n    )\n    inverse_simple = simple.pseudoinverse()\n    result = []\n    for component in components:\n        candidates = []\n        for root in positive:\n            coordinates = vector(QQ,root)*inverse_simple\n            if not all(x in ZZ and x >= 0 for x in coordinates):\n                continue\n            support = tuple(i for i,x in enumerate(coordinates) if x)\n            if support and all(i in component for i in support):\n                candidates.append((sum(coordinates),root,coordinates))\n        _,root,coordinates = max(candidates,key=lambda item:item[0])\n        result.append((component,vector(ZZ,root),vector(ZZ,coordinates)))\n    return result\n\n\ndef intersection(left,right,ns):\n    return ZZ(vector(ZZ,left)*ns*vector(ZZ,right))\n\n\ndef build_chamber_context(frame):\n    ns = block_diagonal_matrix(U,-frame)\n    simple,positive = deterministic_simple_roots_local(frame)\n    cartan = simple*frame*simple.transpose()\n    components = connected_components_local(cartan)\n\n    fiber = vector(ZZ,[1,0]+[0]*frame.nrows())\n    zero = vector(ZZ,[-1,1]+[0]*frame.nrows())\n\n    curves = [("O",zero)]\n    for index,root in enumerate(simple.rows(),1):\n        curves.append(\n            (f"R{index}",vector(ZZ,[0,0]+list(root)))\n        )\n    affine = highest_roots_local(frame,simple,positive)\n    for component_index,(_,root,_) in enumerate(affine,1):\n        curves.append((\n            f"Theta0_{component_index}",\n            fiber-vector(ZZ,[0,0]+list(root)),\n        ))\n\n    return {\n        "frame":frame,\n        "ns":ns,\n        "simple":simple,\n        "cartan":cartan,\n        "components":components,\n        "fiber":fiber,\n        "zero":zero,\n        "curves":tuple(curves),\n        "affine":tuple(affine),\n        "cvp_cache":{},\n    }\n\n\ndef chamber_reduce(divisor,curves,ns):\n    divisor = vector(ZZ,divisor)\n    sequence = []\n    while True:\n        for name,curve in curves:\n            pairing = intersection(divisor,curve,ns)\n            if pairing < 0:\n                divisor += pairing*curve\n                sequence.append((name,pairing))\n                assert divisor*ns*divisor == 0\n                break\n        else:\n            return divisor,tuple(sequence)\n\n\ndef exact_component_nearest_shifts(context, component, target):\n    subgram = context["cartan"].matrix_from_rows_and_columns(\n        component,component\n    )\n    target = vector(QQ,target)\n\n    integer_part = vector(\n        ZZ,[ZZ(floor(value)) for value in target]\n    )\n    fractional = vector(QQ,target-integer_part)\n    key = (tuple(component),tuple(fractional))\n\n    cached = context["cvp_cache"].get(key)\n    if cached is None:\n        z0 = vector(\n            ZZ,[ZZ(floor(-value)) for value in fractional]\n        )\n        x0 = fractional+vector(QQ,z0)\n        best = QQ(x0*subgram*x0)\n\n        inverse = subgram.inverse()\n        ranges = []\n        for i in range(subgram.nrows()):\n            radius2 = QQ(best*inverse[i,i])\n            radius = ZZ(0)\n            while QQ(radius*radius) < radius2:\n                radius += 1\n            lo = ZZ(ceil(-fractional[i]-radius))\n            hi = ZZ(floor(-fractional[i]+radius))\n            ranges.append(range(int(lo),int(hi)+1))\n\n        winners = []\n        for entries in product(*ranges):\n            z = vector(ZZ,entries)\n            x = fractional+vector(QQ,z)\n            value = QQ(x*subgram*x)\n            if value < best:\n                best = value\n                winners = [tuple(z)]\n            elif value == best:\n                winners.append(tuple(z))\n        cached = (best,tuple(sorted(set(winners))))\n        context["cvp_cache"][key] = cached\n\n    _,winners = cached\n    return tuple(\n        vector(ZZ,winner)-integer_part\n        for winner in winners\n    )\n\n\ndef exact_nearest_root_shifts(context,root_coordinates):\n    component_winners = []\n    for component in context["components"]:\n        target = vector(\n            QQ,[root_coordinates[i] for i in component]\n        )\n        winners = exact_component_nearest_shifts(\n            context,component,target\n        )\n        component_winners.append((component,winners))\n\n    shifts = []\n    for choices in product(*(item[1] for item in component_winners)):\n        full = [ZZ(0)]*context["simple"].nrows()\n        for (component,_),choice in zip(component_winners,choices):\n            for index,value in zip(component,choice):\n                full[index] = ZZ(value)\n        shifts.append(vector(ZZ,full))\n    return tuple(shifts)\n\n\ndef effective_shortest_section(\n    context,reduced,root_coordinates,mw_projection\n):\n    frame = context["frame"]\n    ns = context["ns"]\n    simple = context["simple"]\n    fiber = context["fiber"]\n    zero = context["zero"]\n\n    shifts = exact_nearest_root_shifts(context,root_coordinates)\n    accepted = []\n    shortest_norm = None\n\n    for root_shift in shifts:\n        short_lift = vector(ZZ,reduced[2:]) + root_shift*simple\n        short_norm = ZZ(short_lift*frame*short_lift)\n        if shortest_norm is None:\n            shortest_norm = short_norm\n        else:\n            assert short_norm == shortest_norm\n\n        assert short_norm % 2 == 0\n        pole = short_norm//2-2\n        section = vector(\n            ZZ,[pole+1,1]+list(short_lift)\n        )\n        assert section*ns*section == -2\n        assert intersection(section,fiber,ns) == 1\n        assert intersection(section,zero,ns) == pole\n\n        pairings = tuple(\n            (name,intersection(section,curve,ns))\n            for name,curve in context["curves"]\n        )\n        if all(value >= 0 for _,value in pairings):\n            accepted.append((\n                section,short_lift,short_norm,pole,root_shift,pairings\n            ))\n\n    if len(accepted) != 1:\n        raise ArithmeticError(\n            f"expected unique effective shortest section; got {len(accepted)} "\n            f"from {len(shifts)} nearest lifts"\n        )\n    return accepted[0],len(shifts)\n\n\ndef component_name(subcartan):\n    rank = subcartan.nrows()\n    determinant = abs(ZZ(subcartan.det()))\n    # Count roots to distinguish D/E if needed.\n    if determinant == rank+1:\n        return f"A{rank}"\n    if rank >= 4 and determinant == 4:\n        return f"D{rank}"\n    if (rank,determinant) == (6,3):\n        return "E6"\n    if (rank,determinant) == (7,2):\n        return "E7"\n    if (rank,determinant) == (8,1):\n        return "E8"\n    return f"rank{rank}_det{determinant}"\n\n\n# ------------------------------------------------------------------\n# Replay only through orbit1222, retaining the generic->CM24 embedding there.\n# ------------------------------------------------------------------\ngeneric = load_matrix(DATA/"kumar_q80_e6_d5_a3_mw3_frame.txt")\nassert generic == q80_child\nspecial = q80_cm24\nembedding = q80_embedding24\n\nwith (DATA/"kumar_q80_to_rootless_path.tsv").open() as handle:\n    canonical = list(csv.DictReader(handle,delimiter="\\t"))\n\nsteps = []\nfor index in (0,1):\n    row = canonical[index]\n    steps.append({\n        "name":f"prefix_q4_{index+1}",\n        "q":ZZ(row["q"]),"a":ZZ(row["a"]),"b":ZZ(row["b"]),\n        "v":tuple(map(ZZ,row["v"].split(","))),\n    })\n\nsteps.extend([\n    {\n        "name":"escape","q":ZZ(6),"a":ZZ(2),"b":ZZ(3),\n        "v":(-5,-3,6,6,-8,-4,2,4,-1,8,-16,-1,0,3,5,-2,-2),\n    },\n    {\n        "name":"orbit424","q":ZZ(4),"a":ZZ(2),"b":ZZ(2),\n        "v":(32,48,-21,28,8,-52,-34,0,18,5,-23,43,9,-18,16,-6,-6),\n    },\n    {\n        "name":"orbit1222","q":ZZ(4),"a":ZZ(2),"b":ZZ(2),\n        "v":(10,53,-192,-114,29,-256,-170,-12,-14,74,-32,-14,-6,-26,-58,84,-28),\n    },\n])\n\nfor step in steps:\n    child,transport = neighbor(\n        generic,step["q"],step["a"],step["b"],vector(ZZ,step["v"])\n    )\n    special_child,child_embedding = enhance_neighbor(\n        transport,embedding,special\n    )\n    assert child == child_embedding*special_child*child_embedding.transpose()\n    generic,special,embedding = child,special_child,child_embedding\n\nspecial_components = root_components(special)\nassert special_components == [\n    (1,2,2),(1,2,2),(1,2,2),(6,42,7),(6,42,7)\n]\nassert generic == embedding*special*embedding.transpose()\n\nprint(\n    f"Q807774DIV|source_special_components={special_components}|"\n    "source_special_ade=3A1+2A6|status=PASS_ORBIT1222_SPECIAL_SOURCE",\n    flush=True,\n)\n\n\n# ------------------------------------------------------------------\n# Specialize the ACTUAL generic q6_7774 divisor before taking its neighbor.\n# ------------------------------------------------------------------\nq6_v = vector(ZZ,(\n    85,2699,1257,7718,3756,-41,3077,-4614,-6615,\n    6032,2584,-1678,121,-736,-913,1,1165\n))\nassert q6_v*generic*q6_v == 12\n\nraw_generic = vector(ZZ,[2,3]+list(q6_v))\nraw_special = vector(\n    ZZ,[2,3]+list(q6_v*embedding)\n)\n\ngeneric_ns = block_diagonal_matrix(U,-generic)\nspecial_ns = block_diagonal_matrix(U,-special)\nassert raw_generic*generic_ns*raw_generic == 0\nassert raw_special*special_ns*raw_special == 0\n\ncontext = build_chamber_context(special)\nassert context["simple"].nrows() == 15\nreduced,reflections = chamber_reduce(\n    raw_special,context["curves"],special_ns\n)\n\ndegree = intersection(reduced,context["fiber"],special_ns)\nd_o = intersection(reduced,context["zero"],special_ns)\nassert degree == 2\n\nframe_part = vector(QQ,reduced[2:])\nroot_coordinates = (\n    frame_part\n    * special\n    * context["simple"].transpose()\n    * context["cartan"].inverse()\n)\nroot_projection = root_coordinates*context["simple"]\nmw_projection = frame_part-root_projection\nmw_height = QQ(mw_projection*special*mw_projection)\n\n(selected,nearest_count) = effective_shortest_section(\n    context,reduced,root_coordinates,mw_projection\n)\n(\n    section,short_lift,short_norm,section_pole,\n    root_shift,section_pairings\n) = selected\n\nresidual = reduced-(degree-1)*context["zero"]-section\nassert intersection(residual,context["fiber"],special_ns) == 0\nassert residual[1] == 0\n\nroot_coefficients = (\n    vector(QQ,residual[2:])*context["simple"].pseudoinverse()\n)\nassert root_coefficients*context["simple"] == vector(QQ,residual[2:])\nassert all(value in ZZ for value in root_coefficients)\n\nfiber_twist = ZZ(residual[0])\n\ncomponent_rows = []\nfor component in context["components"]:\n    subcartan = context["cartan"].matrix_from_rows_and_columns(\n        component,component\n    )\n    name = component_name(subcartan)\n    coeffs = tuple(ZZ(root_coefficients[i]) for i in component)\n    rootcoords = tuple(QQ(root_coordinates[i]) for i in component)\n    section_simple_pairings = tuple(\n        intersection(\n            section,\n            vector(ZZ,[0,0]+list(context["simple"].row(i))),\n            special_ns,\n        )\n        for i in component\n    )\n    component_rows.append((\n        name,component,coeffs,rootcoords,section_simple_pairings\n    ))\n\nnonzero_section_pairings = tuple(\n    (name,value) for name,value in section_pairings if value\n)\n\nprint(\n    f"Q807774DIV|D.F={degree}|D.O={d_o}|"\n    f"P.O={section_pole}|MWheight={mw_height}|"\n    f"shortnorm={short_norm}|fiber_twist={fiber_twist}|"\n    f"nearest={nearest_count}|reflections={len(reflections)}|"\n    f"section_nonzero_pairings={nonzero_section_pairings}|"\n    "status=PASS_SPECIALIZED_DIVISOR_GEOMETRY",\n    flush=True,\n)\n\nfor index,(name,component,coeffs,rootcoords,pairings) in enumerate(\n    component_rows,1\n):\n    print(\n        f"Q807774DIVCOMP|index={index}|ade={name}|"\n        f"simple_indices={tuple(i+1 for i in component)}|"\n        f"vertical_coeffs={coeffs}|"\n        f"root_coordinates={rootcoords}|"\n        f"section_pairings={pairings}|"\n        "status=PASS_COMPONENT",\n        flush=True,\n    )\n\nsupport = tuple(\n    (\n        index,\n        name,\n        tuple(i+1 for i in component),\n        coeffs,\n    )\n    for index,(name,component,coeffs,_,_) in enumerate(component_rows,1)\n    if any(coeffs)\n)\n\nprint(\n    f"Q807774DIV|vertical_support={support}|"\n    f"vertical_L1={sum(abs(value) for value in root_coefficients)}|"\n    f"vertical_max={max(abs(value) for value in root_coefficients)}|"\n    f"root_shift={tuple(root_shift)}|"\n    "status=PASS_EXACT_SPECIAL_VERTICAL_DECOMPOSITION",\n    flush=True,\n)\n\n# Regression/diagnostic against the earlier candidate census.\nprint(\n    f"Q807774DIVDIAG|generic_height=219/28|"\n    f"special_height={mw_height}|height_drop={QQ(219)/28-mw_height}|"\n    f"generic_PO=3|special_PO={section_pole}|"\n    f"generic_vertical=(0,-1,-1,0,0,0,0,0,0)|"\n    f"special_vertical_components={support}|"\n    "status=PASS_SPECIALIZATION_DELTA",\n    flush=True,\n)\n\n# The q6 child itself must match the independently transported lattice result.\nq6_child,q6_transport = neighbor(generic,ZZ(6),ZZ(2),ZZ(3),q6_v)\nq6_special_child,q6_child_embedding = enhance_neighbor(\n    q6_transport,embedding,special\n)\nassert q6_child == (\n    q6_child_embedding*q6_special_child*q6_child_embedding.transpose()\n)\nq6_special_components = root_components(q6_special_child)\nassert q6_special_components == [\n    (1,2,2),(1,2,2),(4,20,5),(4,20,5),(5,30,6)\n]\n\nprint(\n    f"Q807774DIV|child_components={q6_special_components}|"\n    "child_ade=2A1+2A4+A5|root_data=(15,74,600)|MW=3|"\n    "status=PASS_Q6_7774_SPECIAL_CHILD_REGRESSION",\n    flush=True,\n)\n\nprint(\n    "Q807774DIV|next=rebuild_RR_from_exact_special_vertical_decomposition|"\n    "status=PASS_READY_FOR_CORRECTED_RESOLVED_MODULE",\n    flush=True,\n)\n'


def main():
    repo = find_repo()
    sage = shutil.which("sage") or "/usr/local/bin/sage"
    if shutil.which("sage") is None and not Path(sage).exists():
        raise SystemExit("sage not found")
    print(f"repo={repo}", flush=True)
    print(f"sage={sage}", flush=True)
    with tempfile.TemporaryDirectory() as td:
        script = Path(td) / "q80_q6_7774_cm24_special_divisor_geometry.sage"
        script.write_text(SAGE_CODE)
        subprocess.run([sage, str(script), str(repo)], check=True)


if __name__ == "__main__":
    main()
